import re
def make_replacer(replace_bytes):
    def replacer(m):
        out = bytearray()
        i = 0
        b = replace_bytes
        while i < len(b):
            if b[i] == ord('$'):
                if i + 1 < len(b) and b[i+1] == ord('$'):
                    out.extend(b'$'); i += 2; continue
                match = re.match(b'^\\$\\{([a-zA-Z0-9_]+)\\}', b[i:])
                if match:
                    try: name = int(match.group(1))
                    except ValueError: name = match.group(1).decode('utf-8')
                    try:
                        val = m.group(name)
                        if val: out.extend(val)
                    except IndexError: pass
                    i += match.end(); continue
                match = re.match(b'^\\$([0-9]+)', b[i:])
                if match:
                    try: name = int(match.group(1))
                    except ValueError: name = match.group(1).decode('utf-8')
                    try:
                        val = m.group(name)
                        if val: out.extend(val)
                    except IndexError: pass
                    i += match.end(); continue
                out.extend(b'$'); i += 1; continue
            out.append(b[i]); i += 1
        return bytes(out)
    return replacer

s = b'\\$1'
r = make_replacer(s)
print(re.sub(b'(A)', r, b'A'))
EOF
